using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_AllEnemies", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_AllEnemies")]
public class DiceSecondActionLogic_AllEnemies : DiceSecondActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		actionFace.SecondBattleAction.AreaCastTargetAmount(currentCorruptedAnimals.activeCorruptedAnimals, actionFace.SecondModifiedActionValue, source);
	}
}
